// ===== shared helpers (auto-inserted at the top of every engine Code node) =====
const S = $('Settings').first().json;
const helpers = this.helpers;
const notes = [];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const errMsg = (e) => String((e && (e.description || e.message)) || e).slice(0, 220);
const statusOf = (e) => {
  const direct = e && (e.httpCode || e.statusCode || (e.response && (e.response.status || e.response.statusCode)) || (e.cause && (e.cause.status || (e.cause.response && e.cause.response.status))));
  if (direct) return String(direct);
  const m = String((e && (e.message || e.description)) || '').match(/status code (\d{3})|^(\d{3})\b/);
  return m ? (m[1] || m[2]) : '';
};

async function http(opts, tries = 3) {
  let lastErr;
  for (let i = 0; i < tries; i++) {
    try {
      return await helpers.httpRequest({ timeout: 60000, json: true, ...opts });
    } catch (e) {
      lastErr = e;
      const code = statusOf(e);
      const retryable = code === '429' || code.startsWith('5') || /timeout|ECONNRESET|socket hang up/i.test(errMsg(e));
      if (i < tries - 1 && retryable) { await sleep(Number(S.retry_wait_ms || 15000) * (i + 1)); continue; }
      throw e;
    }
  }
  throw lastErr;
}

// ---- web search: rotates over every search service you have a key for ----
// Order: monthly-renewing free ones first (Tavily, Exa, Firecrawl), then one-time free credits (Linkup, Serper).
// Each service has its own daily cap (keys.txt: TAVILY_DAILY_CAP, EXA_DAILY_CAP ...). When one is used up or
// refuses (no credits / rate limit), the next one takes over. Kept under the old name "tavily" for the rest of the code.
const budget = { tavily: Number(S.max_searches_per_node || S.max_tavily_per_node || 60) };
let tavilyUsed = 0;
const sToday = () => new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
function sQuota(id) {
  const sdx = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
  sdx.sq = sdx.sq || {};
  const q = (sdx.sq[id] = sdx.sq[id] || {});
  if (q.day !== sToday()) { q.day = sToday(); q.used = 0; q.off = false; }
  return q;
}
const linkedinOnly = (opt) => (opt.domains || []).some((d) => /linkedin/.test(d));
const SEARCHERS = [
  { id: 'tavily', key: () => S.tavily_key, cap: () => Number(S.tavily_daily_cap || S.daily_tavily_cap || 33),
    run: async (query, opt) => {
      const body = { query, search_depth: 'basic', max_results: opt.max || 6, include_answer: false, include_raw_content: !!opt.raw };
      if (opt.domains) body.include_domains = opt.domains;
      if (opt.exclude) body.exclude_domains = opt.exclude;
      if (opt.time_range) body.time_range = opt.time_range;
      const r = await http({ method: 'POST', url: (S.tavily_base || 'https://api.tavily.com') + '/search', headers: { Authorization: 'Bearer ' + S.tavily_key, 'Content-Type': 'application/json' }, body }, 2);
      return (r.results || []).map((x) => ({ title: x.title, url: x.url, content: x.content, raw: x.raw_content }));
    } },
  { id: 'exa', key: () => S.exa_key, cap: () => Number(S.exa_daily_cap || 40),
    run: async (query, opt) => {
      const body = { query, numResults: Math.min(opt.max || 6, 25), contents: { text: { maxCharacters: opt.raw ? 6000 : 700 } } };
      if (opt.domains) body.includeDomains = opt.domains;
      if (opt.exclude) body.excludeDomains = opt.exclude;
      if (opt.time_range === 'week') body.startPublishedDate = new Date(Date.now() - 7 * 864e5).toISOString();
      const r = await http({ method: 'POST', url: 'https://api.exa.ai/search', headers: { 'x-api-key': S.exa_key, 'Content-Type': 'application/json' }, body }, 2);
      return (r.results || []).map((x) => ({ title: x.title, url: x.url, content: x.text, raw: x.text }));
    } },
  { id: 'firecrawl', key: () => S.firecrawl_key, cap: () => Number(S.firecrawl_daily_cap || 30),
    run: async (query, opt) => {
      const q = linkedinOnly(opt) ? query + ' site:linkedin.com/in' : query;
      const body = { query: q.slice(0, 480), limit: Math.min(opt.max || 6, 20), country: 'IN' };
      if (opt.time_range === 'week') body.tbs = 'qdr:w';
      const r = await http({ method: 'POST', url: 'https://api.firecrawl.dev/v2/search', headers: { Authorization: 'Bearer ' + S.firecrawl_key, 'Content-Type': 'application/json' }, body }, 2);
      const list = Array.isArray(r.data) ? r.data : ((r.data || {}).web || []);
      return list.map((x) => ({ title: x.title, url: x.url, content: x.description || x.markdown }));
    } },
  { id: 'linkup', key: () => S.linkup_key, cap: () => Number(S.linkup_daily_cap || 60),
    run: async (query, opt) => {
      const body = { q: query, depth: 'standard', outputType: 'searchResults', maxResults: opt.max || 6 };
      if (opt.domains) body.includeDomains = opt.domains;
      if (opt.exclude) body.excludeDomains = opt.exclude;
      const r = await http({ method: 'POST', url: 'https://api.linkup.so/v1/search', headers: { Authorization: 'Bearer ' + S.linkup_key, 'Content-Type': 'application/json' }, body }, 2);
      return (r.results || []).filter((x) => x.type !== 'image').map((x) => ({ title: x.name, url: x.url, content: x.content }));
    } },
  { id: 'serper', key: () => S.serper_key, cap: () => Number(S.serper_daily_cap || 80),
    run: async (query, opt) => {
      // Serper's free plan refuses some search operators: then fall back to a plain-words query
      const simple = sQuota('serper').simple;
      const plain = (t) => t.replace(/["()]/g, ' ').replace(/\bOR\b/g, ' ').replace(/\s+/g, ' ').trim();
      const q = simple ? plain(query) + (linkedinOnly(opt) ? ' linkedin' : '') : (linkedinOnly(opt) ? query + ' site:linkedin.com/in' : query);
      const body = { q: q.slice(0, 380), num: Math.min(opt.max || 6, 20), gl: 'in' };
      if (opt.time_range === 'week') body.tbs = 'qdr:w';
      const r = await http({ method: 'POST', url: 'https://google.serper.dev/search', headers: { 'X-API-KEY': S.serper_key, 'Content-Type': 'application/json' }, body }, 2);
      return (r.organic || []).map((x) => ({ title: x.title, url: x.link, content: x.snippet }));
    } },
];
// how many searches are left today across all services
function searchLeft() {
  return SEARCHERS.filter((p) => p.key()).reduce((s, p) => { const q = sQuota(p.id); return s + (q.off ? 0 : Math.max(0, p.cap() - q.used)); }, 0);
}
async function tavily(query, opt = {}) {
  if (budget.tavily <= 0) { notes.push('Search budget for this step used up; skipped: ' + query.slice(0, 60)); return []; }
  budget.tavily--; tavilyUsed++;
  query = String(query).slice(0, 380);
  for (const p of SEARCHERS) {
    if (!p.key()) continue;
    const q = sQuota(p.id);
    if (q.off || q.used >= p.cap() || (q.pause || 0) > Date.now()) continue;
    q.used++;
    const shape = (res) => res.map((x) => ({ title: String(x.title || '').slice(0, 200), url: String(x.url || ''),
      content: String(x.content || '').slice(0, 700), raw: opt.raw ? String(x.raw || '').slice(0, 6000) : '', via: p.id }));
    try {
      return shape(await p.run(query, opt));
    } catch (e) {
      q.used--;                                                    // failed requests don't count against the free allowance
      const code = statusOf(e), msg = errMsg(e);
      if (/pattern not allowed/i.test(msg) && !q.simple) {        // Serper free plan: retry once with a plain query
        q.simple = true;
        try { q.used++; return shape(await p.run(query, opt)); } catch (e2) { q.used--; q.off = true; notes.push(p.id + ' search stopped for today: ' + errMsg(e2).slice(0, 80)); continue; }
      }
      if (code === '429' && /per ?min|req\/min|too many requests|rate limit/i.test(msg) && !/credit|quota|insufficient|month/i.test(msg)) {
        q.pause = Date.now() + 65000;                              // per-minute limit: rest this service for a minute, use the others
        continue;
      }
      if (['401', '402', '403', '429', '432', '433'].includes(code) || /credit|quota|limit|insufficient|exceed|unauthori/i.test(msg)) {
        q.off = true; notes.push(p.id + ' search stopped for today: ' + msg.slice(0, 80));
      } else notes.push('Web search failed on ' + p.id + ' (' + query.slice(0, 40) + '): ' + msg.slice(0, 80));
    }
  }
  notes.push('No search service left today; skipped: ' + query.slice(0, 50));
  return [];
}

// ---- Gemini (free tier) — picks a working model automatically ----
const GEMINI_PREFERRED = ['gemini-3.8-flash', 'gemini-3.6-flash', 'gemini-3.5-flash', 'gemini-3.5-flash-lite',
  'gemini-3.1-flash-lite', 'gemini-2.5-flash', 'gemini-flash-latest'];
const staticData = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
let lastGemini = 0;
async function listGeminiModels() {
  try {
    const r = await http({ method: 'GET', url: S.gemini_base + '/v1beta/models', qs: { pageSize: 200 },
      headers: { 'x-goog-api-key': S.gemini_key } }, 2);
    return (r.models || [])
      .filter((m) => (m.supportedGenerationMethods || []).includes('generateContent'))
      .map((m) => String(m.name || '').replace(/^models\//, ''))
      .filter((n) => /flash/.test(n) && !/(tts|image|live|audio|embed|transcribe|robotics|computer|native|thinking)/.test(n));
  } catch (e) { notes.push('Could not list Gemini models: ' + errMsg(e)); return []; }
}
function rankModels(avail) {
  const pref = GEMINI_PREFERRED.filter((m) => avail.includes(m));
  const rest = avail.filter((m) => !pref.includes(m) && !/preview|exp/.test(m))
    .sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
  return pref.concat(rest);
}
async function geminiCall(model, prompt) {
  const r = await http({
    method: 'POST',
    url: S.gemini_base + '/v1beta/models/' + model + ':generateContent',
    headers: { 'x-goog-api-key': S.gemini_key, 'Content-Type': 'application/json' },
    body: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.2 },
    },
  }, 4);
  const parts = (((r.candidates || [])[0] || {}).content || {}).parts || [];
  return parts.map((p) => p.text || '').join('');
}
async function gemini(prompt) {
  const gap = Number(S.gemini_gap_ms || 4500);
  const wait = lastGemini + gap - Date.now();
  if (wait > 0) await sleep(wait);
  lastGemini = Date.now();
  const wanted = String(S.gemini_model || 'auto');
  let candidates = [staticData.geminiModel, wanted !== 'auto' ? wanted : null].filter(Boolean);
  let listed = false;
  for (let i = 0; i < 8; i++) {
    if (!candidates.length) {
      if (listed) break;
      listed = true;
      const avail = await listGeminiModels();
      candidates = rankModels(avail);
      if (!candidates.length) candidates = GEMINI_PREFERRED.slice();
    }
    const model = candidates.shift();
    try {
      const text = await geminiCall(model, prompt);
      staticData.geminiModel = model;
      return parseJSON(text);
    } catch (e) {
      const code = statusOf(e);
      if (code === '404' || code === '400' && /not found|not supported|unknown model/i.test(errMsg(e))) {
        if (staticData.geminiModel === model) delete staticData.geminiModel;
        continue;
      }
      if (code === '401' || code === '403') throw new Error('Gemini rejected the key (' + code + '). Check GEMINI_KEY in keys.txt.');
      throw e;
    }
  }
  throw new Error('No Gemini model available for this key. Open aistudio.google.com and check the key works.');
}
function parseJSON(t) {
  try { return JSON.parse(t); } catch (e) {
    const m = String(t).match(/[\[{][\s\S]*[\]}]/);
    if (m) { try { return JSON.parse(m[0]); } catch (e2) { /* fall through */ } }
    throw new Error('The AI reply was not valid JSON. First part: ' + String(t).slice(0, 200));
  }
}

// ---- your Google Sheet (through the small Apps Script you deploy — no Google Cloud setup needed) ----
async function sheet(action, payload = {}) {
  let r = await http({
    method: 'POST',
    url: S.sheet_script_url,
    headers: { 'Content-Type': 'application/json' },
    body: { secret: S.sheet_secret, action, ...payload },
  }, 3);
  if (typeof r === 'string') {
    if (/<html/i.test(r)) throw new Error('The Google Sheet script returned a web page instead of data. Re-check the Web App URL and that "Who has access" is set to "Anyone" (guide step 2).');
    r = parseJSON(r);
  }
  if (!r || r.ok !== true) throw new Error('Google Sheet script: ' + ((r && r.error) || 'no reply'));
  return r;
}

// ---- small utilities ----
const GATED = ['rocketreach.co', 'zoominfo.com', 'signalhire.com', 'contactout.com', 'apollo.io', 'lusha.com',
  'crunchbase.com', 'theorg.com', 'leadiq.com', 'adapt.io', 'seamless.ai', 'clearbit.com', 'uplead.com',
  'datanyze.com', 'kaspr.io', 'getprospect.com', 'snov.io', 'hunter.io', 'tracxn.com', 'wellfound.com', 'glassdoor.co.in', 'glassdoor.com'];
const NOT_ORG_SITE = ['linkedin.com', 'naukri.com', 'indeed.com', 'glassdoor', 'wellfound.com', 'instahyre.com', 'iimjobs.com',
  'cutshort.io', 'crunchbase.com', 'tracxn.com', 'wikipedia.org', 'facebook.com', 'twitter.com', 'x.com', 'instagram.com',
  'youtube.com', 'medium.com', 'economictimes', 'inc42.com', 'yourstory.com', 'ambitionbox.com', 'google.com', 'quora.com', 'reddit.com'];
const host = (u) => { const m = String(u || '').match(/^[a-z][a-z0-9+.-]*:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
const isGated = (u) => GATED.some((g) => host(u).endsWith(g));
const cleanDomain = (d) => String(d || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
// ===== end helpers =====

// ===== email checking =====
// 1) free self-check: ask the company's mail server directly (SMTP "RCPT TO", nothing is ever sent) — unlimited, no key
// 2) if the server won't say, fall back to free API quotas: QuickEmailVerification (100/day), MailboxValidator,
//    ZeroBounce, Hunter - and only then your paid Reoon credits — each only if its key is in keys.txt, each capped per day
// Also tries several address patterns (first.last, first, firstlast, flast ...) and remembers what works per company.
let net = null, dnsP = null;
try { net = require('net'); dnsP = require('dns').promises; } catch (e) { /* not allowed in this n8n: APIs only */ }
const VSD = staticData;
VSD.dom = VSD.dom || {};
VSD.q = VSD.q || {};
const vToday = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
const domInfo = (d) => (VSD.dom[d] = VSD.dom[d] || {});

async function mxOf(domain) {
  const d = domInfo(domain);
  if (d.mx !== undefined && d.mxDay === vToday) return d.mx;
  d.mxDay = vToday; d.mx = ''; d.mxErr = '';
  try {
    if (dnsP) {
      const r = await dnsP.resolveMx(domain);
      r.sort((a, b) => a.priority - b.priority);
      d.mx = r.length ? r[0].exchange : '';
    } else {
      const r = await http({ method: 'GET', url: (S.dns_base || 'https://dns.google') + '/resolve', qs: { name: domain, type: 'MX' } }, 2);
      const a = (r.Answer || []).map((x) => String(x.data).split(' ')).sort((x, y) => Number(x[0]) - Number(y[0]));
      d.mx = a.length ? a[0][1].replace(/\.$/, '') : '';
    }
  } catch (e) { d.mx = ''; d.mxErr = String((e && e.code) || 'error'); }
  if (!d.mx && !d.mxErr) d.mxErr = 'ENODATA';
  if (d.mxErr && !/ENOTFOUND|ENODATA/.test(d.mxErr)) d.mxDay = '';   // temporary DNS problem: try again next time
  return d.mx;
}

const BLOCKED_RE = /block|spamhaus|blacklist|black list|listed|reputation|policy|not allowed|denied|5\.7\.\d|dynamic|residential|rbl|barracuda/i;
// One SMTP conversation: EHLO, MAIL FROM:<>, then RCPT TO for each address. Returns per-address code + text.
function smtpProbe(mx, addrs, timeoutMs) {
  return new Promise((resolve) => {
    const out = { codes: [], error: '', blocked: false };
    let buf = '', step = 0, done = false, sock;
    const finish = () => {
      if (done) return; done = true; clearTimeout(timer);
      try { sock.write('QUIT\r\n'); } catch (e) { /* ignore */ }
      try { sock.destroy(); } catch (e) { /* ignore */ }
      resolve(out);
    };
    const timer = setTimeout(() => { out.error = out.error || 'timeout'; finish(); }, timeoutMs);
    try { sock = net.createConnection({ port: Number(S.smtp_port || 25), host: mx }); } catch (e) { out.error = String(e.message); return finish(); }
    sock.setEncoding('utf8');
    sock.on('error', (e) => { out.error = String(e.code || e.message); finish(); });
    sock.on('close', () => { if (!done) { out.error = out.error || 'closed'; finish(); } });
    const send = (l) => { try { sock.write(l + '\r\n'); } catch (e) { out.error = 'write'; finish(); } };
    sock.on('data', (chunk) => {
      buf += chunk;
      // a reply is complete when a line starts with "NNN " (space, not dash)
      const m = buf.match(/(?:^|\r?\n)(\d{3}) [^\r\n]*\r?\n/);
      if (!m) return;
      const reply = buf; buf = '';
      const code = Number(m[1]);
      if (step === 0) { // greeting
        if (code !== 220) { out.error = 'greeting ' + code; out.blocked = BLOCKED_RE.test(reply); return finish(); }
        step = 1; return send('EHLO ' + (S.smtp_helo || 'lead-finder.local'));
      }
      if (step === 1) {
        if (code !== 250) { out.error = 'ehlo ' + code; out.blocked = BLOCKED_RE.test(reply); return finish(); }
        step = 2; return send('MAIL FROM:<' + (S.smtp_from || '') + '>');
      }
      if (step === 2) {
        if (code !== 250) { out.error = 'mailfrom ' + code; out.blocked = BLOCKED_RE.test(reply); return finish(); }
        step = 3; return send('RCPT TO:<' + addrs[0] + '>');
      }
      // RCPT replies
      out.codes.push({ code, text: reply.replace(/\s+/g, ' ').trim().slice(0, 160) });
      if (code >= 500 && BLOCKED_RE.test(reply) && !/user|mailbox|recipient|address|unknown|exist|not found|no such/i.test(reply)) { out.blocked = true; return finish(); }
      if (out.codes.length < addrs.length) return send('RCPT TO:<' + addrs[out.codes.length] + '>');
      finish();
    });
  });
}

function rnd() { return 'zq' + Math.random().toString(36).slice(2, 10) + 'x'; }
// returns { results: {addr: 'valid'|'invalid'|'unknown'}, catchAll: bool, usable: bool }
async function selfCheck(domain, addrs) {
  if (!net || S.smtp_selfcheck === false || String(S.smtp_selfcheck) === 'false') return { usable: false };
  const d = domInfo(domain);
  if (d.blockedDay === vToday) return { usable: false };
  const mx = await mxOf(domain);
  if (!mx) return { usable: false, noMx: true };
  VSD.sc = VSD.sc && VSD.sc.day === vToday ? VSD.sc : { day: vToday, n: 0 }; VSD.sc.n++;
  const probe = addrs.concat([rnd() + '@' + domain]);
  const r = await smtpProbe(mx, probe, Number(S.smtp_timeout_ms || 20000));
  if (r.blocked || (r.error && !r.codes.length)) {
    if (r.blocked) d.blockedDay = vToday;
    if (r.error) notes.push('Self-check ' + domain + ': ' + (r.blocked ? 'mail server refuses checks from this PC' : r.error));
    return { usable: false };
  }
  const res = {};
  addrs.forEach((a, i) => {
    const c = (r.codes[i] || {}).code;
    res[a] = !c ? 'unknown' : (c === 250 || c === 251) ? 'valid' : (c >= 550 && c <= 553) ? 'invalid' : 'unknown';
  });
  const rc = (r.codes[addrs.length] || {}).code;
  const catchAll = rc === 250 || rc === 251;
  if (rc) d.catchAll = catchAll;
  const anyKnown = Object.values(res).some((v) => v !== 'unknown');
  return { usable: anyKnown, results: res, catchAll };
}

// ---- free API fallbacks ----
const PROVIDERS = [
  { id: 'qev', name: 'QuickEmailVerification', key: () => S.qev_key, cap: () => Number(S.qev_daily_cap || 100),
    run: async (email) => {
      const r = await http({ method: 'GET', url: 'https://api.quickemailverification.com/v1/verify', qs: { email, apikey: S.qev_key } }, 1);
      if (r.success === false || r.success === 'false') throw new Error('QEV: ' + (r.message || 'failed'));
      if (String(r.accept_all) === 'true') return 'catch_all';
      return r.result === 'valid' ? 'valid' : r.result === 'invalid' ? 'invalid' : 'unknown';
    } },
  { id: 'mbv', name: 'MailboxValidator', key: () => S.mailboxvalidator_key, cap: () => Number(S.mailboxvalidator_daily_cap || 10),
    run: async (email) => {
      const r = await http({ method: 'GET', url: 'https://api.mailboxvalidator.com/v1/validation/single', qs: { email, key: S.mailboxvalidator_key, format: 'json' } }, 1);
      if (r.error_code) throw new Error('MailboxValidator: ' + r.error_message);
      const T = (v) => String(v).toLowerCase() === 'true';
      if (T(r.is_catchall)) return 'catch_all';
      if (T(r.is_verified)) return 'valid';
      if (T(r.is_smtp) && !T(r.is_server_down) && !T(r.is_greylisted) && String(r.is_verified).toLowerCase() === 'false') return 'invalid';
      return 'unknown';
    } },
  { id: 'zb', name: 'ZeroBounce', key: () => S.zerobounce_key, cap: () => Number(S.zerobounce_daily_cap || 3),
    run: async (email) => {
      const r = await http({ method: 'GET', url: 'https://api.zerobounce.net/v2/validate', qs: { email, api_key: S.zerobounce_key, ip_address: '' } }, 1);
      if (r.error) throw new Error('ZeroBounce: ' + r.error);
      const st = String(r.status || '').toLowerCase();
      return st === 'valid' ? 'valid' : st === 'invalid' ? 'invalid' : st === 'catch-all' ? 'catch_all' : 'unknown';
    } },
  { id: 'hunter', name: 'Hunter', key: () => S.hunter_key, cap: () => Number(S.hunter_verify_daily_cap || 2),
    run: async (email) => {
      const r = await http({ method: 'GET', url: (S.hunter_base || 'https://api.hunter.io') + '/v2/email-verifier', qs: { email, api_key: S.hunter_key } }, 1);
      const st = String(((r || {}).data || {}).status || '').toLowerCase();
      return st === 'valid' ? 'valid' : st === 'invalid' ? 'invalid' : st === 'accept_all' ? 'catch_all' : 'unknown';
    } },
  { id: 'reoon', name: 'Reoon', key: () => S.reoon_key, cap: () => Number(S.reoon_daily_cap || 20),
    run: async (email) => {
      const r = await http({ method: 'GET', url: (S.reoon_base || 'https://emailverifier.reoon.com') + '/api/v1/verify', qs: { email, key: S.reoon_key, mode: 'power' }, timeout: 60000 }, 1);
      const st = String(r.status || '').toLowerCase();
      return ['safe', 'valid'].includes(st) ? 'valid' : ['invalid', 'disabled', 'disposable', 'spamtrap'].includes(st) ? 'invalid' : st === 'catch_all' ? 'catch_all' : 'unknown';
    } },
];
function quota(p) {
  const q = (VSD.q[p.id] = VSD.q[p.id] || {});
  if (q.day !== vToday) { q.day = vToday; q.used = 0; q.off = false; }
  return q;
}
async function apiCheck(email) {
  for (const p of PROVIDERS) {
    if (!p.key()) continue;
    const q = quota(p);
    if (q.off || q.used >= p.cap()) continue;
    q.used++;
    try {
      const v = await p.run(email);
      if (v !== 'unknown') return { verdict: v, by: p.name };
    } catch (e) {
      const code = statusOf(e);
      if (['401', '402', '403', '429'].includes(code) || /credit|quota|limit|insufficient/i.test(errMsg(e))) { q.off = true; notes.push(p.name + ' stopped for today: ' + errMsg(e).slice(0, 80)); }
      else notes.push(p.name + ': ' + errMsg(e).slice(0, 80));
    }
  }
  return { verdict: 'unknown', by: '' };
}
function apiQuotaLeft() {
  return PROVIDERS.filter((p) => p.key()).reduce((s, p) => { const q = quota(p); return s + (q.off ? 0 : Math.max(0, p.cap() - q.used)); }, 0);
}

// ---- address patterns ----
const PATTERNS = ['first.last', 'first', 'firstlast', 'flast', 'f.last', 'first_last', 'last.first', 'firstl', 'last'];
function makeAddr(pat, f, l, domain) {
  const m = { 'first.last': l && `${f}.${l}`, first: f, firstlast: l && f + l, flast: l && f[0] + l, 'f.last': l && `${f[0]}.${l}`,
    first_last: l && `${f}_${l}`, 'last.first': l && `${l}.${f}`, firstl: l && f + l[0], last: l };
  return m[pat] ? m[pat] + '@' + domain : '';
}
// Find the best address for a person. Returns { email, status, pattern }
async function findEmail(nameParts, domain, companyPattern) {
  const f = nameParts[0], l = nameParts.length > 1 ? nameParts[nameParts.length - 1] : '';
  const d = domInfo(domain);
  const order = [d.pattern, companyPattern].concat(PATTERNS).filter((p, i, a) => p && p !== 'none' && a.indexOf(p) === i);
  const cands = []; const patOf = {};
  for (const p of order) { const a = makeAddr(p, f, l, domain); if (a && !cands.includes(a)) { cands.push(a); patOf[a] = p; } }
  if (!cands.length) return { email: '', status: 'LinkedIn only' };
  const best = cands[0];
  if (!(await mxOf(domain))) return { email: '', status: 'LinkedIn only (no mail server found for ' + domain + ')' };
  if (d.catchAll === true && d.catchAllDay && (Date.now() - d.catchAllDay) < 30 * 864e5) return { email: best, status: 'Unverified (domain accepts all)' };

  // 1) free self-check (all patterns in one connection)
  const sc = await selfCheck(domain, cands.slice(0, Number(S.smtp_patterns || 6)));
  if (sc.usable) {
    if (sc.catchAll) { d.catchAll = true; d.catchAllDay = Date.now(); return { email: best, status: 'Unverified (domain accepts all)' }; }
    const hit = cands.find((a) => sc.results[a] === 'valid');
    if (hit) { d.pattern = patOf[hit]; return { email: hit, status: 'Verified (mail server check)', pattern: patOf[hit] }; }
    if (cands.slice(0, Number(S.smtp_patterns || 6)).every((a) => sc.results[a] === 'invalid')) return { email: '', status: 'No working address found - use LinkedIn' };
  }
  // 2) free API quotas — try the 2 most likely patterns
  const bad = new Set(sc.usable ? cands.filter((a) => sc.results[a] === 'invalid') : []);
  for (const a of cands.filter((x) => !bad.has(x)).slice(0, 2)) {
    if (apiQuotaLeft() <= 0) break;
    const r = await apiCheck(a);
    if (r.verdict === 'valid') { d.pattern = patOf[a]; return { email: a, status: 'Verified (' + r.by + ')', pattern: patOf[a] }; }
    if (r.verdict === 'catch_all') { d.catchAll = true; d.catchAllDay = Date.now(); return { email: best, status: 'Unverified (domain accepts all)' }; }
    if (r.verdict === 'invalid') { bad.add(a); continue; }
    break;
  }
  const guess = cands.find((a) => !bad.has(a));
  return guess ? { email: guess, status: 'Unverified guess' } : { email: '', status: 'No working address found - use LinkedIn' };
}
