function usableFirstName(name) {
  const parts = String(name || '').replace(/\(.*?\)/g, ' ').split(/\s+/).map((p) => p.replace(/[^A-Za-z'-]/g, '')).filter(Boolean);
  const good = parts.filter((p) => p.length > 1 && !/^(dr|mr|ms|mrs|ca|cfa)$/i.test(p));
  const f = good[0] || '';
  return f ? f[0].toUpperCase() + f.slice(1).toLowerCase() : '';
}

