  return d;
}

// EMAIL CHECKER: checks each UNSENT lead's email ONCE with the free mail-server check (no email is ever sent).
//  - the leads your outreach agent will send next are checked FIRST; while they are checked they are held (Approved blank) and released right after
//  - works                      -> Email Confidence = "High – verified ..."          -> released to your agent (Approved = Y)
//  - wrong format, other works  -> Email cell corrected                               -> released
//  - nothing works              -> Status = "Email failed check"                      -> never sent
//  - can't tell (accepts all / server won't answer) -> "Shady – ..." + Sent From = SHADY_SENDER; sent only from that account
//    once your sender agent has set Config SHADY_SENDER_READY = YES (until then they wait, marked in Notes)
// Follow-ups are never touched (only Status = Not Contacted).
const TABS = ['PM', 'IB', 'VC', 'PE', 'Generalist', 'Consulting'];
const today = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
const stamp = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 16).replace('T', ' ');
const T0 = Date.now(), BUDGET = Number(S.time_budget_ms || 22 * 60e3);   // stay well inside n8n's 30-min limit
const HELD = '[held for email check]', WAIT = '[Shady - waits for sender rule]';
const stripMarks = (n) => String(n || '').replace(/\s*\[held for email check\]/g, '').replace(/\s*\[Shady - waits for sender rule\]/g, '').trim();
const withMark = (n, m) => (stripMarks(n) + ' ' + m).trim();

// ---- shared settings with your sender agent (Config tab) ----
const cfgRows = ((await sheet('getTab', { tab: 'Config' })).rows || []).slice(1);
const cfgGet = (k) => { const r = cfgRows.find((x) => String(x[0]).trim() === k); return r ? String(r[1] || '').trim() : null; };
const SHADY_SENDER = cfgGet('SHADY_SENDER') || 'ameet.iiciitkgp@gmail.com';
const READY = /^y/i.test(cfgGet('SHADY_SENDER_READY') || 'NO');
const seedRows = [];
if (cfgGet('SHADY_SENDER') === null) seedRows.push(['SHADY_SENDER', SHADY_SENDER, 'Lead Finder marks emails it cannot verify as "Shady" (Email Confidence starts with Shady) and puts this account in Sent From. Sender agent: send Shady rows ONLY from this account.']);
if (cfgGet('SHADY_SENDER_READY') === null) seedRows.push(['SHADY_SENDER_READY', 'NO', 'Sender agent sets this to YES once it sends "Shady" rows only from SHADY_SENDER. Until then Lead Finder keeps Shady rows on hold (Approved blank). It sets Approved = Y itself after YES.']);
if (seedRows.length) await sheet('appendRows', { tab: 'Config', header: ['Setting', 'Value', 'Notes'], rows: seedRows });

const all = (await sheet('checkList', { tabs: TABS })).rows || [];
const tally = { checked: 0, verified: 0, corrected: 0, failed: 0, shady: 0, released: 0, heldNow: 0 };
const nameParts = (n) => String(n || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\(.*?\)/g, ' ')
  .replace(/\b(dr|mr|ms|mrs|ca|cfa)\.?\s+/g, '').split(/[^a-z]+/).filter((s) => s.length > 1);

// ---- order: exactly the order your agent sends in (Fit score high first, tabs taking turns); approved leads first ----
const byTab = {};
for (const r of all) (byTab[r.tab] = byTab[r.tab] || []).push(r);
for (const t of TABS) (byTab[t] || []).sort((a, b) => b.fit - a.fit || a.row - b.row);
const rr = (pred) => { const out = []; let more = true; const q = {}; for (const t of TABS) q[t] = (byTab[t] || []).filter(pred);
  while (more) { more = false; for (const t of TABS) if (q[t].length) { out.push(q[t].shift()); more = true; } } return out; };
const sendNext = rr((r) => r.approved === 'Y' || r.held);
const others = rr((r) => !(r.approved === 'Y' || r.held));
const order = sendNext.concat(others);
const batch = order.slice(0, Number(S.check_batch || 500));

// ---- hold the leads about to be sent until they are checked ----
const holdUpdates = batch.filter((r) => r.approved === 'Y' && !r.held).map((r) => ({ tab: r.tab, row: r.row, id: r.id, set: { Approved: '', Notes: withMark(r.notes, HELD) } }));
for (let i = 0; i < holdUpdates.length; i += 100) { const res = await sheet('updateCells', { updates: holdUpdates.slice(i, i + 100) }); tally.heldNow += res.updated || 0; }
const wasApproved = new Set(batch.filter((r) => r.approved === 'Y' || r.held).map((r) => r.id));   // restore these to Y when done (held ones: they were Y before)
const done = new Set();

const pending = [];
let written = 0, skipped = 0;
async function flush(force) {
  if (!pending.length || (!force && pending.length < 40)) return;
  const chunk = pending.splice(0, pending.length);
  for (let i = 0; i < chunk.length; i += 100) { const res = await sheet('updateCells', { updates: chunk.slice(i, i + 100) }); written += res.updated || 0; skipped += res.skipped || 0; }
}
// what a finished lead gets: released to the agent (Y), or kept on hold
function finish(r, set, release) {
  set.Notes = release ? stripMarks(r.notes) : withMark(r.notes, WAIT);
  if (release) { if (wasApproved.has(r.id) || r.waiting) set.Approved = 'Y'; } else set.Approved = '';
  if (release && set.Approved === 'Y') tally.released++;
  pending.push({ tab: r.tab, row: r.row, id: r.id, set });
  done.add(r.id);
}

async function checkOne(r) {
  const cur = String(r.email).trim().toLowerCase();
  const domain = cur.split('@')[1];
  const nm = nameParts(r.name);
  const f = nm[0] || '', l = nm.length > 1 ? nm[nm.length - 1] : '';
  const d = domInfo(domain);
  const set = {};
  let verdict = 'unknown', via = 'mail server check';
  const legacy = /^Checked \d{4}-\d{2}-\d{2}: (domain accepts|mail server would not)/i.exec(r.conf || '');
  if (r.waiting && /^Shady/i.test(r.conf || '')) {
    verdict = /accepts every/i.test(r.conf) ? 'acceptsAll' : 'unknown';   // already judged: just release / keep waiting
    return finishVerdict(r, set, verdict, via, cur, true);
  }
  if (legacy) {                                          // checked once already in an earlier run: do not check again, label it
    verdict = /accepts/i.test(legacy[1]) ? 'acceptsAll' : 'unknown';
    if (verdict === 'unknown' && apiQuotaLeft() > 0) { const a = await apiCheck(cur); if (a.verdict === 'valid') { verdict = 'verified'; via = a.by; } else if (a.verdict === 'invalid') verdict = 'failed'; else if (a.verdict === 'catch_all') verdict = 'acceptsAll'; }
    return finishVerdict(r, set, verdict, via, cur, false);
  }
  const cands = [cur]; const patOf = {};
  if (f) for (const p of [d.pattern].concat(PATTERNS)) { const a = p && makeAddr(p, f, l, domain); if (a && !cands.includes(a)) { cands.push(a); patOf[a] = p; } }
  const probe = cands.slice(0, Number(S.smtp_patterns || 6));
  if (!(await mxOf(domain)) && /ENOTFOUND|ENODATA/.test(d.mxErr || 'ENODATA')) {
    verdict = 'failed'; set['Email Confidence'] = `Checked ${today}: domain has no mail server`;
  } else if (d.catchAll === true && d.catchAllDay && (Date.now() - d.catchAllDay) < 30 * 864e5) {
    verdict = 'acceptsAll';
  } else {
    const sc = await selfCheck(domain, probe);
    if (sc.usable) {
      if (sc.catchAll) { d.catchAll = true; d.catchAllDay = Date.now(); verdict = 'acceptsAll'; }
      else if (sc.results[cur] === 'valid') verdict = 'verified';
      else {
        const hit = probe.find((a) => sc.results[a] === 'valid');
        if (hit) { verdict = 'corrected'; set['Email'] = hit; if (patOf[hit]) d.pattern = patOf[hit]; }
        else if (probe.every((a) => sc.results[a] === 'invalid')) verdict = 'failed';
      }
    }
    if (verdict === 'unknown' && apiQuotaLeft() > 0) {
      const a = await apiCheck(cur);
      if (a.verdict === 'valid') { verdict = 'verified'; via = a.by; }
      else if (a.verdict === 'catch_all') { d.catchAll = true; d.catchAllDay = Date.now(); verdict = 'acceptsAll'; }
      else if (a.verdict === 'invalid') verdict = 'failed';
    }
  }
  return finishVerdict(r, set, verdict, via, cur, false, probe.length);
}

function finishVerdict(r, set, verdict, via, cur, already, nProbe) {
  if (!already) tally.checked++;
  if (verdict === 'verified' || verdict === 'corrected') {
    tally[verdict]++;
    const was = verdict === 'corrected' ? `; was ${cur}` : '';
    const orig = /^High\s*[–-]\s*verified/i.test(r.conf || '') ? '' : (r.conf ? ` · before: ${String(r.conf).slice(0, 60)}` : '');
    set['Email Confidence'] = `High – verified by ${via} (${today}${was})${orig}`;
    finish(r, set, true);
  } else if (verdict === 'failed') {
    tally.failed++;
    set['Status'] = 'Email failed check';
    set['Email Confidence'] = set['Email Confidence'] || `Checked ${today}: mailbox does not exist (tried ${nProbe || 'several'} formats) - use LinkedIn`;
    set.Notes = stripMarks(r.notes); set.Approved = ''; pending.push({ tab: r.tab, row: r.row, id: r.id, set }); done.add(r.id);   // never sent
  } else {
    tally.shady++;
    set['Email Confidence'] = verdict === 'acceptsAll' ? `Shady – domain accepts every address, can't be verified (checked ${today})` : `Shady – mail server would not answer (checked ${today})`;
    set['Sent From'] = SHADY_SENDER;
    finish(r, set, READY);
  }
  return flush(false);
}

for (let i = 0; i < batch.length && Date.now() - T0 < BUDGET * 0.6; i += 4)
  await Promise.all(batch.slice(i, i + 4).map((r) => checkOne(r).catch((e) => { notes.push('Check ' + r.email + ': ' + errMsg(e).slice(0, 60)); })));
await flush(true);

// anything still held (ran out of time, or an error): give it back so no lead is stuck
const stuck = batch.filter((r) => !done.has(r.id) && (r.approved === 'Y' || r.held) && !r.waiting);
const back = stuck.map((r) => ({ tab: r.tab, row: r.row, id: r.id, set: { Approved: 'Y', Notes: stripMarks(r.notes) } }));
for (let i = 0; i < back.length; i += 100) await sheet('updateCells', { updates: back.slice(i, i + 100) });
// held-over leads from an earlier run that were not in this batch: give them back too
const orphan = order.slice(batch.length).filter((r) => r.held).map((r) => ({ tab: r.tab, row: r.row, id: r.id, set: { Approved: 'Y', Notes: stripMarks(r.notes) } }));
for (let i = 0; i < orphan.length; i += 100) await sheet('updateCells', { updates: orphan.slice(i, i + 100) });
// Shady leads waiting for the sender rule, released as soon as your sender agent says YES
if (READY) {
  const rel = order.filter((r) => r.waiting && !done.has(r.id)).map((r) => ({ tab: r.tab, row: r.row, id: r.id, set: { Approved: 'Y', Notes: stripMarks(r.notes) } }));
  for (let i = 0; i < rel.length; i += 100) { const res = await sheet('updateCells', { updates: rel.slice(i, i + 100) }); tally.released += res.updated || 0; }
}
tally.returnedUnchecked = stuck.length + orphan.length;

if (batch.length) await sheet('appendRows', { tab: 'Email Check Log', header: ['When', 'Checked', 'Verified', 'Corrected', 'Failed (stopped)', 'Accepts all', 'Server would not answer', 'Rows changed meanwhile'],
  rows: [[stamp + (READY ? '' : ' (shady on hold)'), tally.checked, tally.verified, tally.corrected, tally.failed, tally.shady + ' shady', tally.released + ' released', skipped]] });
// ---- PASS 2: people in the Daily tabs whose email was only a guess ----
// Re-checks them with the free mail-server check. Newly verified -> copied into your outreach agent's tab with drafts.
// No address works -> marked "use LinkedIn". Each row is re-tried every few days, at most a few times.
const D2 = { checked: 0, verified: 0, toOutreach: {}, dead: 0, stillUnknown: 0, acceptsAll: 0 };
const DAILY_TRACKS = ['APM', 'Generalist', 'VC', 'PE', 'IB', 'Consulting'];
const OUT_HEADER2 = ['ID', 'Track', 'Name', 'First Name', 'Title', 'Company', 'Domain', 'Location', 'Profile URL', 'Source', 'Email', 'Email Confidence',
  'Approved', 'Personalization Hook', 'Fit Score', 'Subject', 'E1 Body', 'FU1 Body', 'FU2 Body', 'FU3 Body', 'FU4 Body', 'Status', 'Emails Sent (of 5)',
  'Date Sent E1', 'Last Sent', 'Next Follow-up Due', 'Gmail Thread ID (all 5 emails share it)', 'Gmail Message ID', 'Reply Outcome', 'Replied Date',
  'Bounce', 'Unsubscribed', 'Notes', 'Queued At', 'Sent From'];
const RETRY = /^(Unverified guess|LinkedIn only \(no mail server found)/i;
const STAMP_RE = /\s*·\s*re-?checked (\d{4}-\d{2}-\d{2}) \((\d+)\)\s*$/;
const everyDays = Number(S.daily_recheck_days || 2), maxTries = Number(S.daily_max_rechecks || 4);
const dailyBatch = Number(S.daily_check_batch || 120);
if (S.daily_recheck !== false && String(S.daily_recheck) !== 'false' && Date.now() - T0 < BUDGET * 0.7) {
  // firm patterns + regions from the Targets tab, auto-approve switch from Config
  const tg = ((await sheet('getTab', { tab: 'Targets' })).rows || []).slice(1);
  const firm = {};
  for (const r of tg) firm[String(r[0]).trim() + '|' + String(r[1]).trim()] = { pattern: String(r[4] || '').trim().toLowerCase(), region: String(r[5] || 'India') };
  let autoApprove = 'YES';
  try {
    for (const r of ((await sheet('getTab', { tab: 'Config' })).rows || [])) if (String(r[0]).trim() === 'LEADFINDER_AUTO_APPROVE') autoApprove = /^n/i.test(String(r[1]).trim()) ? 'NO' : 'YES';
  } catch (e) { /* no Config tab: default YES */ }
  const seen = (await sheet('getSeen', { tabs: TABS })).seen || { emails: [], links: [] };
  const seenE = new Set(seen.emails.map((x) => x.toLowerCase()));
  const liKey2 = (u) => String(u || '').toLowerCase().replace(/^https?:\/\/(\w+\.)?/, '').replace(/[?#].*$/, '').replace(/\/$/, '');
  const seenL = new Set(seen.links.map(liKey2));

  // pick rows: newest first, shared fairly between the 6 tabs
  const cut = new Date(Date.now() + 5.5 * 3600e3 - everyDays * 864e5).toISOString().slice(0, 10);
  const per = Math.max(1, Math.ceil(dailyBatch / DAILY_TRACKS.length));
  const todo = [];
  for (const tr of DAILY_TRACKS) {
    const g = await sheet('getTab', { tab: 'Daily - ' + tr });
    const rows = g.rows || [];
    if (rows.length < 2) continue;
    const h = rows[0].map((x) => String(x).trim());
    const c = { name: h.indexOf('Name'), title: h.indexOf('Title'), co: h.indexOf('Company'), li: h.indexOf('LinkedIn'), em: h.indexOf('Email'), st: h.indexOf('Email status'), dom: h.indexOf('Company domain') };
    if (c.li < 0 || c.st < 0 || c.em < 0) continue;
    let taken = 0;
    for (let i = rows.length - 1; i >= 1 && taken < per; i--) {
      const r = rows[i], st = String(r[c.st] || '');
      const base = st.replace(STAMP_RE, '').trim(), m = st.match(STAMP_RE);
      if (!RETRY.test(base) || !r[c.li] || !r[c.dom]) continue;
      if (m && (m[1] > cut || Number(m[2]) >= maxTries)) continue;
      if (seenL.has(liKey2(r[c.li]))) continue;                   // already in an outreach tab
      todo.push({ tr, row: i + 1, name: r[c.name], title: r[c.title], company: r[c.co], li: String(r[c.li]), email: String(r[c.em] || ''),
        domain: cleanDomain(r[c.dom]), base, tries: m ? Number(m[2]) : 0 });
      taken++;
    }
  }

  const dUpdates = [], promote = {};
  async function recheck(p) {
    const nm = nameParts(p.name);
    if (!nm.length || !p.domain) return;
    const f = firm[p.tr + '|' + String(p.company).trim()] || {};
    const r = await findEmail(nm, p.domain, f.pattern && f.pattern !== 'none' ? f.pattern : '');
    D2.checked++;
    const tag = ` · rechecked ${today} (${p.tries + 1})`;
    const set = {};
    if (r.status.startsWith('Verified') && r.email && !seenE.has(r.email.toLowerCase())) {
      D2.verified++; seenE.add(r.email.toLowerCase());
      const tab = OUTREACH_TAB[p.tr];
      set['Email'] = r.email; set['Email status'] = r.status + ` · found on re-check ${today}, added to ${tab} tab`;
      (promote[tab] = promote[tab] || []).push({ p, r, region: f.region || 'India' });
    } else if (/^No working address/.test(r.status)) {
      D2.dead++; set['Email'] = ''; set['Email status'] = 'No working address found - use LinkedIn' + tag;
    } else if (/accepts all/.test(r.status)) {
      D2.acceptsAll++; set['Email status'] = 'Unverified (domain accepts all)' + tag;
    } else {
      D2.stillUnknown++; set['Email status'] = (/^LinkedIn only/.test(r.status) ? r.status : 'Unverified guess') + tag;
      if (r.email && r.email !== p.email) set['Email'] = r.email;
    }
    dUpdates.push({ tab: 'Daily - ' + p.tr, row: p.row, keyCol: 'LinkedIn', key: p.li, set });
  }
  for (let i = 0; i < todo.length && Date.now() - T0 < BUDGET; i += 4) await Promise.all(todo.slice(i, i + 4).map((p) => recheck(p).catch((e) => notes.push('Re-check ' + p.name + ': ' + errMsg(e).slice(0, 60)))));

  // newly verified -> your outreach agent's tabs (same format + drafts as the morning run)
  const stampId = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(2, 13).replace(/[-T]/g, '');   // yymmddHH
  for (const tab of Object.keys(promote)) {
    const out = promote[tab].map(({ p, r, region }, k) => {
      const d = buildDraft(p.tr, p.name, p.company);
      const row = new Array(OUT_HEADER2.length).fill('');
      row[0] = `${ID_PREFIX[tab]}-LC${stampId}${String(k + 1).padStart(2, '0')}`;
      row[1] = tab; row[2] = p.name; row[3] = d.first; row[4] = p.title; row[5] = String(p.company).replace(/\s*\(.*\)\s*$/, '');
      row[6] = p.domain; row[7] = /global/i.test(region) ? '' : 'India'; row[8] = p.li;
      row[9] = 'Lead Finder (LinkedIn search, re-checked ' + today + ')';
      row[10] = r.email; row[11] = 'High – ' + r.status.replace(/^Verified \((.*)\)$/, 'verified by $1') + ' (' + today + ')';
      row[12] = autoApprove === 'NO' ? '' : 'Y';
      row[13] = d.hook; row[14] = 4; row[15] = d.subject;
      row[16] = d.e1; row[17] = d.fu1; row[18] = d.fu2; row[19] = d.fu3; row[20] = d.fu4;
      row[21] = 'Not Contacted';
      row[32] = 'Added by Lead Finder (email check) ' + today;
      return row;
    });
    await sheet('appendRows', { tab, header: OUT_HEADER2, rows: out });
    D2.toOutreach[tab] = out.length;
  }
  for (let i = 0; i < dUpdates.length; i += 100) {
    const res = await sheet('updateCells', { updates: dUpdates.slice(i, i + 100) });
    if ((res.skipped || 0) && !(res.updated || 0)) notes.push('Daily tabs not updated: sheet connector needs the new version');
  }
  if (D2.checked) await sheet('appendRows', { tab: 'Email Check Log', header: ['When', 'Checked', 'Verified', 'Corrected', 'Failed (stopped)', 'Accepts all', 'Server would not answer', 'Rows changed meanwhile'],
    rows: [[stamp + ' (Daily tabs)', D2.checked, D2.verified + ' (added to outreach: ' + (Object.entries(D2.toOutreach).map(([k, v]) => k + ' ' + v).join(', ') || 'none') + ')', '', D2.dead + ' (use LinkedIn)', D2.acceptsAll, D2.stillUnknown, '']] });
}

return [{ json: Object.assign({ batch: batch.length, candidates: all.length, written, skipped, shadySenderReady: READY, notes: [...new Set(notes)].slice(0, 8) }, tally, { daily: D2 }) }];
